  v_revision text := 'bebs-catalog-2026-09-13-v214';
begin
  select id into v_company_id
  from public.companies
  where lower(name) = lower('Beb''s Adega e Tabacaria')
  order by created_at asc
  limit 1;

  if v_company_id is null then
    raise exception 'Empresa Beb''s Adega e Tabacaria não encontrada.';
  end if;

  if not exists (select 1 from public.company_state where company_id = v_company_id) then
    raise exception 'company_state não encontrado para a Beb''s. Rode os SQLs 004, 005 e 006 antes deste.';
  end if;

  update public.company_state
  set state = jsonb_set(
                jsonb_set(
                  jsonb_set(
                    state,
                    '{products}',
                    v_products,
                    true
                  ),
                  '{suspendedSales}',
                  '[]'::jsonb,
                  true
                ),
                '{catalogRevision}',
                to_jsonb(v_revision),
                true
              ),
      version = version + 1,
      updated_at = now(),
      updated_by = null
  where company_id = v_company_id;

  -- Registra o reset no histórico técnico, quando a tabela da v2.1.1 estiver disponível.
  if to_regclass('public.company_state_events') is not null then
    insert into public.company_state_events (
      company_id, event_id, client_id, reason, state_hash, state_size_bytes, applied_version, created_at
    )
    select
      v_company_id,
      'catalog-reset-v214-' || extract(epoch from clock_timestamp())::bigint::text,
      'sql-migration',
      'Catálogo Bebs substituído pela lista consolidada de 13/09/2026',
      md5(cs.state::text),
      octet_length(cs.state::text),
      cs.version,
      now()
    from public.company_state cs
    where cs.company_id = v_company_id;
  end if;
end $$;

notify pgrst, 'reload schema';

-- Conferência: deve retornar 295 produtos e a revisão v2.1.4.
select
  c.name as empresa,
  cs.state->>'catalogRevision' as catalog_revision,
  jsonb_array_length(cs.state->'products') as total_produtos,
  cs.version,
  cs.updated_at
from public.company_state cs
join public.companies c on c.id = cs.company_id
where lower(c.name) = lower('Beb''s Adega e Tabacaria');
